svg.script:
(() => {
    const frame = document.getElementById('site');
    const page = "<!DOCTYPE html>
<html lang="en">
<head>
<base id="svg-base">
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>New Tab</title>

    <style>
@font-face { font-family: Mojangles; src: url('mojangles.otf') format('opentype'); font-display: swap; }
* { box-sizing: border-box; }
html { min-height: 100%; }
body {
    margin: 0; min-height: 100svh; padding: 0 20px 72px;
    background: #53644b url('images/background.png') center / cover fixed no-repeat;
    color: #fff; font: 18px Mojangles, monospace; text-shadow: 2px 2px #333;
}
@keyframes panoramaPan { from { background-position: 44% center; } to { background-position: 56% center; } }
body { animation: panoramaPan 90s ease-in-out infinite alternate; }
body::before { content: ''; position: fixed; inset: 0; background: #0002; pointer-events: none; z-index: -1; }
button, input, select { font: inherit; }
a { color: inherit; }
.hidden { display: none !important; }
.view { width: min(760px, 100%); margin: auto; padding: 28px 0 20px; }
.title-container { position: relative; width: min(610px, 92%); margin: 0 auto 40px; }
h1 { margin: 0; text-align: center; }
h1 img { display: block; width: 100%; height: auto; image-rendering: pixelated; }
h2 { text-align: center; }
p { line-height: 1.45; }
h2.splash-text {
    position: absolute; right: -20px; bottom: -5px; max-width: 58%; margin: 0;
    font-size: clamp(13px, 1.8vw, 21px); color: #ffff55; text-shadow: 2px 2px #3f3f00;
    text-align: center; transform: rotate(-17deg); animation: splashPulse .65s ease-in-out infinite alternate;
    pointer-events: none;
}
@keyframes splashPulse { from { transform: rotate(-17deg) scale(.96); } to { transform: rotate(-17deg) scale(1.04); } }
/* The console's long, low buttons retain the original local texture. */
.custom-button, .btn-close {
    position: relative; display: flex; align-items: center; justify-content: center;
    width: 100%; min-width: 0; min-height: 42px; margin: 0; padding: 9px 16px;
    border: 0; border-radius: 0; background: #777; overflow: hidden;
    color: #fff; text-shadow: 2px 2px #333; font: inherit; font-size: 19px;
    text-align: center; text-decoration: none; cursor: pointer; image-rendering: pixelated;
}
/* Fixed end caps and repeated center tiles preserve the texture's proportions. */
.mc-left, .mc-right, .mc-middle-tile {
    background-image: url('images/minecraft-button.png');
    background-size: var(--mc-sprite-width, 313px) var(--mc-sprite-height, 42px);
    background-repeat: no-repeat;
    image-rendering: pixelated;
}
.mc-left, .mc-right {
    display: block; position: absolute; top: 0; bottom: 0;
    width: var(--mc-cap-width, 5px); z-index: 1; pointer-events: none;
}
.mc-left { left: 0; background-position: 0 0; }
.mc-right { right: 0; background-position: var(--mc-right-offset, -308px) 0; }
.mc-middle {
    display: flex; position: absolute; inset: 0 var(--mc-cap-width, 5px);
    overflow: hidden; z-index: 1; pointer-events: none;
}
.mc-middle-tile { flex: 0 0 auto; height: 100%; background-position: var(--mc-center-offset, -5px) 0; }
.button-text { position: relative; z-index: 2; overflow-wrap: anywhere; }
.custom-button:hover, .btn-close:hover, .custom-button:focus-visible, .btn-close:focus-visible {
    color: #ffffa0; outline: 2px solid #fff; outline-offset: -3px; filter: brightness(1.16);
}
.custom-button:active, .btn-close:active { filter: brightness(.85); }
.custom-button:disabled { opacity: .5; cursor: default; }
:focus-visible { outline: 2px solid #fff; outline-offset: 3px; }
#menu-view { min-height: calc(100svh - 90px); padding-top: clamp(38px, 10vh, 86px); }
#menu-view .title-container { width: min(700px, 94%); margin-bottom: clamp(46px, 8vh, 72px); }
#menu-view > div:last-child { width: min(560px, 94%); margin: auto; display: grid; gap: 12px; }
#menu-view .custom-button, #menu-view .btn-close { min-height: 60px; font-size: 24px; }
.small-button-row { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) 60px; gap: 10px; }
#to-credits-btn { grid-column: 1; grid-row: 1; }
#to-options-btn { grid-column: 2; grid-row: 1; }
#mute-btn { grid-column: 3; grid-row: 1; width: 60px; margin: 0; padding: 0; }
#mute-btn .button-text { font-size: 25px; }
/* Legacy Console window: raised gray rim, dark inset content. */
#mc-tabbed-container {
    width: min(800px, 100%); aspect-ratio: 472 / 352; margin: auto; position: relative;
    background: url('images/menuload.png') center / 100% 100% no-repeat; image-rendering: pixelated;
}
#mc-tabbed-container.mc-tab-bg-create { background-image: url('images/menucreate.png'); }
.console-tabs { position: absolute; top: 3.5%; left: 11%; width: 57%; height: 9%; display: flex; z-index: 2; }
.console-tabs button {
    flex: 1; min-width: 0; padding: 0; border: 0; background: transparent;
    color: transparent; text-shadow: none; cursor: pointer;
}
.console-tabs button[aria-selected='true'] { order: -1; }
.console-tabs button:focus-visible { outline: 2px solid #fff; outline-offset: -5px; }
.console-window { position: absolute; inset: 17% 13% 7% 14%; color: #303030; text-shadow: none; }
.tab-content-pane { height: 100%; }
#tab-content-load { display: flex !important; flex-direction: column; }
.mc-tab-bg-create #tab-content-load { display: none !important; }
.mc-menu-panel, .mc-options-screen, dialog {
    background: #929292; color: #303030; text-shadow: none;
    border: 3px solid #222; border-radius: 0; padding: 22px;
    box-shadow: inset 3px 3px #eee, inset -3px -3px #555, 3px 3px #0007;
}
.mc-panel-header { font-size: 22px; text-align: center; margin-bottom: 16px; }
#feeling-lucky-btn { width: min(380px, 100%); margin: auto; }
#lucky-status { text-align: center; font-size: 13px; margin: 7px 0 14px; min-height: 19px; }
.console-list {
    flex: 1; min-height: 0; overflow-y: auto; padding: 10px;
    border: 2px solid; border-color: #555 #bbb #bbb #555; background: #7d7d7d;
    scrollbar-color: #c6c6c6 #555;
}
.list-heading { color: #fff; text-shadow: 2px 2px #444; margin: 4px 4px 8px; font-size: 16px; }
.mc-grid-layout, #g8mes-grid { display: grid; grid-template-columns: 1fr; gap: 6px; min-width: 0; }
#user-links-grid { margin-bottom: 16px; }
.empty-slots { margin: 0 4px 4px; color: #eee; text-shadow: 1px 1px #444; font-size: 13px; }
.mc-grid-layout .custom-button { font-size: 16px; min-height: 40px; }
.saved-link-button { padding-right: 48px; }
.mc-input-area { width: min(450px, 100%); margin: 22px auto 10px; display: grid; gap: 10px; }
.mc-input-area label { font-size: 16px; }
.mc-input-area #save-custom-link-btn { margin-top: 12px; }
.mc-textbox, .mc-search-box, .mc-options-input {
    width: 100%; min-width: 0; min-height: 42px; padding: 9px 12px;
    background: #777; border: 2px solid; border-color: #444 #fff #fff #444; border-radius: 0;
    color: #fff; font-size: 17px; text-shadow: 1px 1px #444;
}
input::placeholder { color: #ddd; opacity: 1; }
.mc-divider, .mc-options-divider { height: 2px; background: #888; border-bottom: 1px solid white; margin: 18px 0; }
.back-button-row { width: min(300px, 100%); margin: 16px auto 0; }
#to-menu-from-pr8xies, #to-menu-from-options { width: min(300px, 100%); margin: 18px auto 0; }
.mc-menu-panel, .mc-options-screen { width: min(640px, 100%); margin: auto; }
.mc-search-box { margin: 0 auto 16px; display: block; }
#g8mes-grid { max-height: 38vh; overflow-y: auto; padding: 8px; background: #808080; border: 2px solid; border-color: #555 #fff #fff #555; }
.gn-catalog-status { min-height: 20px; margin: 12px 0; font-size: 15px; text-align: center; }
#g8mes-grid.gn-games-grid { grid-template-columns: repeat(auto-fill, minmax(125px, 1fr)); gap: 10px; max-height: 38vh; }
.gn-empty { grid-column: 1 / -1; color: #fff; text-align: center; }
.gn-game-card { display: flex; flex-direction: column; min-width: 0; padding: 5px; border: 2px solid; border-color: #ddd #444 #444 #ddd; border-radius: 0; background: #666; color: #fff; text-shadow: 1px 1px #222; cursor: pointer; }
.gn-game-card:hover, .gn-game-card:focus-visible { background: #858585; color: #ffffa0; }
.gn-game-art { display: grid; place-items: center; position: relative; width: 100%; aspect-ratio: 1; overflow: hidden; background: #444; color: #aaa; }
.gn-game-art img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.gn-game-name { display: flex; align-items: center; justify-content: center; min-height: 46px; padding: 7px 2px 2px; font-size: 15px; line-height: 1.2; overflow-wrap: anywhere; }
#g8me-load-more-btn, #g8me-retry-btn { margin-top: 10px; }
#gn-game-player { position: fixed; inset: 0; z-index: 100; display: flex; flex-direction: column; background: #111; text-shadow: none; }
.gn-player-toolbar { display: flex; align-items: center; gap: 8px; padding: 8px; background: #929292; border-bottom: 3px solid #333; }
#gn-game-player:fullscreen .gn-player-toolbar { display: none; }
.gn-player-toolbar h2 { flex: 1; min-width: 0; margin: 0 8px; font-size: 18px; color: #222; text-align: left; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.gn-player-toolbar .custom-button { width: auto; min-height: 40px; font-size: 15px; }
.gn-player-stage, #gn-frame-host { flex: 1; min-height: 0; position: relative; }
#gn-frame-host { width: 100%; height: 100%; }
#gn-frame-host iframe { display: block; width: 100%; height: 100%; border: 0; background: #111; }
.gn-player-message { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 12px; padding: 20px; background: #222; text-align: center; }
.gn-player-message .custom-button { width: min(280px, 100%); }
body:has(#gn-game-player:not(.hidden)) { overflow: hidden; }
@media (max-width: 600px) {
    #g8mes-grid.gn-games-grid { grid-template-columns: repeat(auto-fill, minmax(105px, 1fr)); }
    .gn-player-toolbar { flex-wrap: wrap; }
    .gn-player-toolbar h2 { flex-basis: 100%; padding-bottom: 4px; }
    .gn-player-toolbar .custom-button { flex: 1; padding: 7px; font-size: 13px; }
}
.mc-options-title { text-align: center; font-size: 24px; margin-bottom: 24px; }
.mc-options-section { display: grid; gap: 18px; }
.mc-option-row { display: grid; grid-template-columns: 1fr 1.1fr; align-items: center; gap: 18px; }
.mc-option-label { font-size: 16px; }
.mc-options-button { font-size: 16px; }
.mc-options-footer { width: min(300px, 100%); margin: auto; }
dialog { width: min(480px, calc(100% - 32px)); }
dialog::backdrop { background: #0007; }
.dialog-content { display: grid; gap: 16px; }
.dialog-content h2 { font-size: 20px; margin: 0; }
.dialog-content p { font-size: 16px; margin: 0; }
.bottom-left-container { position: fixed; bottom: 12px; left: 20px; display: flex; gap: 8px; }
.bottom-left-container a { display: block; line-height: 0; }
.bottom-left-icon { height: 96px; width: auto; image-rendering: pixelated; }
footer { position: fixed; bottom: 16px; right: 20px; color: #fff; font-size: 22px; line-height: 1.4; text-align: right; }
.credits-screen { position: fixed; inset: 0; width: 100%; max-width: none; height: 100vh; padding: 0; overflow: hidden; background-image: linear-gradient(rgba(0, 0, 0, 0.6), rgba(0, 0, 0, 0.6)), url('images/dirt.jpg'); background-repeat: repeat; /* Added proper property */ background-size: 1024px; z-index: 10;}
.credits-scroll { text-align: center; animation: credits-scroll 45s linear forwards; }
.credits-scroll h1 { font-size: 42px; margin-bottom: 50px; }
.credits-scroll h2 { font-size: 28px; margin: 8px 0; }
.credits-scroll p { color: #ccc; margin: 45px 0 10px; }
.credits-spacer { height: 100vh; }
@keyframes credits-scroll { from { transform: translateY(0); } to { transform: translateY(-2200px); } }
#credits-exit-btn { position: fixed; top: 16px; right: 16px; z-index: 20; width: 44px; height: 44px; background: #555; border: 2px solid #aaa; color: white; cursor: pointer; }
body:has(#credits-view:not(.hidden)) footer, body:has(#credits-view:not(.hidden)) .bottom-left-container { display: none; }
@media (max-width: 600px) {
    body { padding: 0 12px 20px; }
    .view { padding-top: 24px; }
    h2.splash-text { right: 0; max-width: 65%; }
    #menu-view .custom-button, #menu-view .btn-close { min-height: 48px; font-size: 18px; }
    .small-button-row { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) 48px; gap: 8px; }
    #mute-btn { width: 48px; }
    #mc-tabbed-container { aspect-ratio: auto; background: none; padding-top: 38px; }
    #mc-tabbed-container.mc-tab-bg-create { background-image: none; }
    .console-tabs { top: 0; left: 0; width: 75%; height: 40px; }
    .console-tabs button { color: #303030; background: #999; border: 3px solid #222; border-bottom: 0; box-shadow: inset 2px 2px #eee; }
    .console-tabs button[aria-selected='true'] { background: #b8b8b8; }
    .console-window { position: static; padding: 18px; background: #929292; border: 3px solid #222; box-shadow: inset 3px 3px #eee, inset -3px -3px #555; }
    .console-list { flex: none; height: 260px; }
    .mc-menu-panel, .mc-options-screen { padding: 16px; }
    .mc-option-row { grid-template-columns: 1fr; gap: 8px; }
    .bottom-left-container { position: static; margin-top: 20px; }
    footer { position: static; max-width: none; margin-top: 10px; text-align: left; }
    #menu-view { min-height: calc(100svh - 130px); }
}
@media (max-height: 720px) and (min-width: 601px) {
    .view { padding-top: 18px; }
    .title-container { width: 450px; margin-bottom: 24px; }
    #g8mes-view .title-container { width: 390px; margin-bottom: 12px; }
    #mc-tabbed-container { width: min(700px, 100%); }
    #menu-view { padding-top: 30px; }
    #menu-view .title-container { width: 600px; margin-bottom: 46px; }
}
@media (prefers-reduced-motion: reduce) {
    body { animation: none; }
    .splash-text { animation: none !important; }
    .credits-scroll { animation: none; }
    .credits-screen { overflow-y: auto; }
    .credits-spacer { height: 40px; }
}

</style>

    <script type="module">
import { links } from "./links.js";
// GN Math integration using the same catalog mirror and fetch-to-iframe approach
// as the supplied Opium reference. Keep this module alongside index.svg.
const SOURCES = [
    {
        catalog: 'https://cdn.jsdelivr.net/gh/freebuisness/assets@main/zones.json',
        html: 'https://cdn.jsdelivr.net/gh/freebuisness/html@main/',
        covers: 'https://cdn.jsdelivr.net/gh/freebuisness/covers@main/'
    },
    {
        catalog: 'https://raw.githubusercontent.com/gn-math/assets/main/zones.json',
        html: 'https://raw.githubusercontent.com/gn-math/html/main/',
        covers: 'https://raw.githubusercontent.com/gn-math/covers/main/'
    }
];
const PAGE_SIZE = 60;

async function fetchWithTimeout(url, options = {}) {
    const timeout = new AbortController();
    const abort = () => timeout.abort();
    if (options.signal?.aborted) abort();
    else options.signal?.addEventListener('abort', abort, { once: true });
    const timer = setTimeout(abort, 20000);
    try {
        const response = await fetch(url, { signal: timeout.signal });
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        // Consume the body before clearing the timeout, including large games.
        return await response.text();
    } finally {
        clearTimeout(timer);
        options.signal?.removeEventListener('abort', abort);
    }
}

function gameDocument(html, url) {
    // Some catalog games use a Google Module / CDATA wrapper.
    const wrapped = html.match(/<Content[^>]*>\s*<!\[CDATA\[([\s\S]*?)\]\]>\s*<\/Content>/i);
    if (wrapped) html = wrapped[1];
    else if (/^\s*<Module\b/i.test(html)) {
        const start = html.search(/<!doctype html|<html\b/i);
        if (start >= 0) html = html.slice(start);
    }
    if (!/<(?:html|head|body|script|div|canvas|!doctype)\b/i.test(html)) {
        throw new Error('The game source did not contain an HTML document.');
    }
    if (/<base\b/i.test(html)) return html;
    const base = new URL('.', url).href.replace(/&/g, '&amp;').replace(/"/g, '&quot;');
    const element = `<base href="${base}">`;
    if (/<head\b[^>]*>/i.test(html)) return html.replace(/<head\b[^>]*>/i, head => head + element);
    if (/<html\b[^>]*>/i.test(html)) return html.replace(/<html\b[^>]*>/i, root => root + `<head>${element}</head>`);
    return element + html;
}

function initializeGnMath({ rebuildButtons, onOpen, onClose }) {
    const grid = document.getElementById('g8mes-grid');
    const search = document.getElementById('g8me-search-input');
    const catalogStatus = document.getElementById('g8me-catalog-status');
    const catalogRetry = document.getElementById('g8me-retry-btn');
    const more = document.getElementById('g8me-load-more-btn');
    const player = document.getElementById('gn-game-player');
    const title = document.getElementById('gn-player-title');
    const host = document.getElementById('gn-frame-host');
    const message = document.getElementById('gn-player-message');
    const status = document.getElementById('gn-player-status');
    const retry = document.getElementById('gn-retry-btn');
    const close = document.getElementById('gn-close-btn');
    const fullscreen = document.getElementById('gn-fullscreen-btn');
    const clickAudio = document.getElementById('clickSound');
    if (!grid || !player) return;

    let games = [];
    let matches = [];
    let shown = 0;
    let activeGame = null;
    let activeRequest = null;
    let generation = 0;
    let returnFocus = null;
    const sound = () => {
        if (!clickAudio) return;
        clickAudio.currentTime = 0;
        clickAudio.play().catch(() => {});
    };
    const exitFullscreenOnEscape = event => {
        if (event.key === 'Escape' && document.fullscreenElement === player) {
            event.preventDefault();
            document.exitFullscreen().catch(() => {});
        }
    };
    document.addEventListener('keydown', exitFullscreenOnEscape, true);

    function updateCount() {
        const query = search.value.trim();
        catalogStatus.textContent = `${matches.length.toLocaleString()}${query ? ' matching' : ''} GN Math games · ${shown.toLocaleString()} shown`;
        more.classList.toggle('hidden', shown >= matches.length);
        more.querySelector('.button-text').textContent = `Load More G8mes (${Math.max(0, matches.length - shown).toLocaleString()} remaining)`;
    }

    function appendGames() {
        const end = Math.min(shown + PAGE_SIZE, matches.length);
        const fragment = document.createDocumentFragment();
        for (const game of matches.slice(shown, end)) {
            const card = document.createElement('button');
            card.type = 'button';
            card.className = 'gn-game-card';
            card.setAttribute('aria-label', `Play ${game.name}`);
            const art = document.createElement('span');
            art.className = 'gn-game-art';
            art.textContent = 'GN';
            art.setAttribute('aria-hidden', 'true');
            const image = document.createElement('img');
            image.src = game.cover;
            image.alt = '';
            image.loading = 'lazy';
            image.decoding = 'async';
            let triedFallback = false;
            image.addEventListener('error', () => {
                if (!triedFallback && game.fallbackCover !== game.cover) {
                    triedFallback = true;
                    image.src = game.fallbackCover;
                } else image.remove();
            });
            art.append(image);
            const label = document.createElement('span');
            label.className = 'gn-game-name';
            label.textContent = game.name;
            card.append(art, label);
            card.addEventListener('click', () => openGame(game, card));
            fragment.append(card);
        }
        shown = end;
        grid.append(fragment);
        updateCount();
        requestAnimationFrame(rebuildButtons);
    }

    function filterGames() {
        const query = search.value.trim().toLocaleLowerCase();
        matches = games.filter(game => game.name.toLocaleLowerCase().includes(query));
        shown = 0;
        grid.replaceChildren();
        grid.scrollTop = 0;
        appendGames();
        if (games.length && !matches.length) {
            const empty = document.createElement('p');
            empty.className = 'gn-empty';
            empty.textContent = 'No g8mes found.';
            grid.append(empty);
        }
    }

    async function loadCatalog() {
        catalogRetry.classList.add('hidden');
        grid.setAttribute('aria-busy', 'true');
        catalogStatus.textContent = 'Loading GN Math games...';
        for (const source of SOURCES) {
            try {
                const data = JSON.parse(await fetchWithTimeout(source.catalog));
                if (!Array.isArray(data)) throw new Error('Invalid catalog');
                const playable = data.filter(game => Number(game.id) >= 0 &&
                    typeof game.name === 'string' && !game.name.startsWith('[!]') && typeof game.url === 'string' &&
                    game.url.startsWith('{HTML_URL}/'));
                if (!playable.length) throw new Error('Empty catalog');
                games = playable.map(game => {
                    const path = game.url.slice('{HTML_URL}/'.length);
                    const coverPath = typeof game.cover === 'string' && game.cover.startsWith('{COVER_URL}/')
                        ? game.cover.slice('{COVER_URL}/'.length) : `${game.id}.png`;
                    return {
                        id: game.id, name: game.name,
                        urls: [...new Set([new URL(path, source.html).href,
                            `https://raw.githubusercontent.com/freebuisness/html/main/${path}`,
                            `https://raw.githubusercontent.com/gn-math/html/main/${path}`])],
                        cover: new URL(coverPath, source.covers).href,
                        fallbackCover: `https://raw.githubusercontent.com/gn-math/covers/main/${coverPath}`
                    };
                }).sort((a, b) => a.name.localeCompare(b.name, undefined, { sensitivity: 'base', numeric: true }));
                grid.setAttribute('aria-busy', 'false');
                filterGames();
                return;
            } catch (error) {
                console.warn('GN Math catalog source unavailable:', source.catalog, error.message);
            }
        }
        grid.setAttribute('aria-busy', 'false');
        catalogStatus.textContent = 'Could not load GN Math. Check your connection and try again.';
        catalogRetry.classList.remove('hidden');
        requestAnimationFrame(rebuildButtons);
    }

    async function openGame(game, trigger = null) {
        sound();
        const wasClosed = player.classList.contains('hidden');
        if (trigger) returnFocus = trigger;
        activeRequest?.abort();
        const request = new AbortController();
        activeRequest = request;
        const current = ++generation;
        activeGame = game;
        host.replaceChildren();
        title.textContent = game.name;
        player.classList.remove('hidden');
        message.classList.remove('hidden');
        retry.classList.add('hidden');
        status.textContent = `Loading ${game.name}...`;
        if (wasClosed) onOpen();
        close.focus();
        requestAnimationFrame(rebuildButtons);
        for (const url of game.urls) {
            try {
                const html = gameDocument(await fetchWithTimeout(url, { signal: request.signal }), url);
                if (current !== generation || request.signal.aborted) return;
                const frame = document.createElement('iframe');
                frame.id = 'gn-game-frame';
                frame.title = game.name;
                frame.allow = 'autoplay; fullscreen; gamepad; clipboard-write';
                frame.allowFullscreen = true;
                frame.addEventListener('load', () => {
                    if (current !== generation) return;
                    message.classList.add('hidden');
                    frame.contentDocument?.addEventListener('keydown', exitFullscreenOnEscape, true);
                    frame.contentWindow?.focus();
                }, { once: true });
                // Fetch the text and run it as HTML; navigating to the CDN's .html
                // URL directly would show plain text instead of starting the game.
                frame.srcdoc = html;
                host.replaceChildren(frame);
                return;
            } catch (error) {
                if (current !== generation || request.signal.aborted) return;
                console.warn('GN Math game source unavailable:', url, error.message);
            }
        }
        if (current !== generation) return;
        status.textContent = `Could not load ${game.name}. Try again or choose another game.`;
        retry.classList.remove('hidden');
        requestAnimationFrame(rebuildButtons);
    }

    async function closeGame() {
        sound();
        ++generation;
        activeRequest?.abort();
        activeGame = null;
        // Removing the iframe stops its scripts, audio, timers, and network activity.
        host.replaceChildren();
        if (document.fullscreenElement === player) await document.exitFullscreen().catch(() => {});
        player.classList.add('hidden');
        onClose();
        returnFocus?.focus({ preventScroll: true });
    }

    search.addEventListener('input', filterGames);
    more.addEventListener('click', () => { sound(); appendGames(); });
    catalogRetry.addEventListener('click', loadCatalog);
    retry.addEventListener('click', () => { if (activeGame) openGame(activeGame); });
    document.getElementById('gn-reload-btn').addEventListener('click', () => { if (activeGame) openGame(activeGame); });
    close.addEventListener('click', closeGame);
    fullscreen.disabled = !player.requestFullscreen;
    fullscreen.addEventListener('click', async () => {
        sound();
        try {
            if (document.fullscreenElement === player) await document.exitFullscreen();
            else await player.requestFullscreen();
        } catch (error) { console.warn('Fullscreen unavailable:', error.message); }
    });
    document.addEventListener('fullscreenchange', () => {
        fullscreen.querySelector('.button-text').textContent = document.fullscreenElement === player ? 'Exit Fullscreen' : 'Fullscreen';
    });
    loadCatalog();
}


