        const doc = win.document;
        doc.open();

        // Set base URL so relative images, CSS, and resources load correctly
        const baseUrl = document.baseURI;

        doc.write(`
            <!DOCTYPE html>
            <html>
            <head>
                <base href="${baseUrl}">
                <title>${document.title}</title>
                <style>
                    html, body {
                        margin: 0;
                        padding: 0;
                        width: 100vw;
                        height: 100vh;
                        overflow: hidden;
                        background-color: #000;
                    }
